/* Frontier use-case gallery (사례관), curated. Data: js/gallery-data.js, generated by tools/build_gallery.py from
   refs/drive/usecases/ (+ first lines in refs/old-claude-design-brief.md), refs/x-frontier-cases/cases.json and
   refs/web-office-cases/cases.json, filtered by tools/curation.json (standouts only, each with a reason).
   Sections: 쇼케이스 (by model family), 오피스 (ranked web cases, X posts, one computer-use demo), Blender.
   X posts: every model attribution and claim is the post's own words → ○ 미확인.
   Web office cases: the five official sources → ● 확인됨 (공식 출처); the third-party tutorial → ○ 미확인.
   Videos never preload; a click swaps the poster for the player. YouTube loads only on click, from youtube-nocookie.
   Remote-only videos get a poster and a link out. */
(function () {
  const A = window.AR, R = window.ARR, G = A.gallery;
  if (!G) return;
  const $ = (s, el = document) => el.querySelector(s);
  const esc = R.esc, raw = R.raw;
  const dlg = $("#gallery"), body = $("#gallery-in");
  const decode = (s) => String(s || "").replace(/&gt;/g, ">").replace(/&lt;/g, "<").replace(/&amp;/g, "&");
  const byKey = new Map(G.items.map((i) => [i.key, i]));
  const inSec = (k) => G.items.filter((i) => i.category === k);
  const sections = G.sections.map((s) => ({ ...s, items: inSec(s.key) })).filter((s) => s.items.length);
  const likes = (a, b) => (b.likes || 0) - (a.likes || 0);

  /* posts that are also on the floor, and the audit's word where it applies */
  const PIECE = {
    "d-OpenAI-2097374640582668336": { id: "science", gate: "감사 B-0 :106: 밀레니엄 문제 본체가 아니라 강제 있는 NS에 대한 주장 단계" },
    "d-zealcaiden-2117359490257629331": { id: "claudia" },
    "d-motion_so-2107136416342061418": { id: "motionso" },
    "d-PrimeIntellect-2108672479007047952": { id: "graph" },
    "x-48": { id: "astra3d" },
    "x-36": { id: "hf" },
  };
  const firstPoster = (it) => { const m = it.media[0]; return m ? (m.type === "img" ? m.src : m.poster) : null; };
  const mmss = (s) => `${Math.floor(s / 60)}:${String(Math.round(s % 60)).padStart(2, "0")}`;
  const status = (it) => it.origin === "web" && it.verified
    ? `<span class="st st-s" data-st="verified">확인됨 (공식 출처)</span>`
    : `<span class="st st-s" data-st="unverified">미확인</span>`;

  /* ── floor: the wall, one block per section ─────── */
  function buildWall() {
    const z = A.zones.gal, world = $("#world");
    if (!z || !world) return;
    const wall = document.createElement("div");
    wall.className = "gal-wall";
    wall.style.cssText = `left:${z.x + 110}px;top:1040px;width:${z.w - 220}px`;
    wall.innerHTML = `
      <button type="button" class="gal-open" data-gal="" aria-label="사례관 열기: 고른 사례 ${G.items.length}건">사례관 열기 <kbd>G</kbd></button>
      <p class="gal-note">X 게시물의 모델 표기와 주장은 확인되지 않았습니다 <span class="st st-s" data-st="unverified">미확인</span></p>
      ${sections.map((s) => `<section class="gal-fam" data-sec="${s.key}" aria-hidden="true"><h3><b>${esc(s.name)}</b> <span>${s.items.length}</span></h3>
        <div class="gal-tiles">${s.items.slice().sort((a, b) => (a.rank || 99) - (b.rank || 99) || likes(a, b)).map((it) => {
          const p = it.thumb || firstPoster(it);
          return `<span class="gal-tile" data-gal="${it.key}" role="presentation">${p ? `<img src="${raw(p)}" alt="" loading="lazy" decoding="async">` : `<i class="gal-ph"><b>${esc(it.author)}</b></i>`}</span>`;
        }).join("")}</div></section>`).join("")}`;
    world.appendChild(wall);
  }

  /* ── room ─────────────────────────────────────────── */
  function media(it) {
    const m = it.media[0];
    if (it.youtube) {
      const th = m && m.src;
      return `<div class="gl-media is-yt" data-orient="landscape">
        <button type="button" class="gl-yt" data-yt="${raw(it.youtube)}" aria-label="${raw(it.name + ": YouTube 영상 불러오기")}">
          ${th ? `<img src="${raw(th)}" alt="" loading="lazy" decoding="async">` : ""}<i aria-hidden="true"></i><span class="gl-dur">YouTube · 누르면 불러옴</span>
        </button></div>`;
    }
    if (!m) return `<div class="gl-media is-ph" data-orient="landscape"><span><b>${esc(it.author)}</b>${esc(it.linkKind)}에서 보기</span></div>`;
    const orient = m.w && m.h ? (m.h > m.w * 1.1 ? "portrait" : "landscape") : "landscape";
    if (m.type === "remote") {
      const local = it.media.find((x) => x.type === "img");
      return `<div class="gl-media is-remote" data-orient="landscape">${m.poster ? `<img src="${raw(m.poster)}" alt="${raw("@" + it.author + " 게시 영상의 한 장면")}" loading="lazy" decoding="async">` : `<span class="gl-ph">영상은 X에만 있음</span>`}
        <a class="gl-ext" href="${raw(it.url)}" target="_blank" rel="noopener noreferrer">영상은 X에서 보기</a>${local ? `<span class="gl-more">이미지도 있음</span>` : ""}</div>`;
    }
    if (m.type === "img") {
      const more = it.media.length > 1 ? `<span class="gl-more">이미지 ${it.media.length}장</span>` : "";
      return `<div class="gl-media" data-orient="${orient}"><img src="${raw(m.src)}" alt="${raw((it.origin === "web" ? it.name : "@" + it.author) + " 이미지")}" loading="lazy" decoding="async">${more}</div>`;
    }
    return `<div class="gl-media is-video" data-orient="${orient}">
      <button type="button" class="gl-play" data-src="${raw(m.src)}" aria-label="${raw("@" + it.author + " 게시 영상 재생" + (m.excerpt ? ", 앞 2분 발췌" : ""))}">
        <img src="${raw(m.poster)}" alt="" loading="lazy" decoding="async"><span class="gl-dur">${mmss(m.dur)}${m.excerpt ? ` <small>앞 2분 발췌 · 원본 ${mmss(m.srcDur)}</small>` : ""}</span><i aria-hidden="true"></i>
      </button></div>`;
  }
  function tile(it, lead) {
    const text = decode(it.text);
    const short = text.length > 220;
    const pc = PIECE[it.key];
    const floorLink = pc ? `<button type="button" class="gl-piece" data-piece="${pc.id}">바닥의 조각: ${esc(A.pieces.find((p) => p.id === pc.id).title)}</button>` : "";
    const claim = it.claim ? it.claim.replace(/ \(unverified: claim in post text only\)$/, "") : it.group;
    const who = it.origin === "web" ? `${esc(it.name)} · ${esc(it.author)}` : `@${esc(it.author)}`;
    return `<li class="gl-item${lead ? " is-lead" : ""}${it.computerUse ? " is-cu" : ""}" id="g-${it.key}">
      ${it.rank ? `<span class="gl-rank" aria-label="순위 ${it.rank}">${it.rank}</span>` : ""}
      ${media(it)}
      <div class="gl-cap">
        ${it.computerUse ? `<p class="gl-flag">컴퓨터 사용 데모 <span>실제 사무 업무가 아니라, 에이전트가 화면을 조작하는 시연</span></p>` : ""}
        ${it.made ? `<p class="gl-made">${esc(decode(it.made))}</p>` : ""}
        ${it.origin === "web" ? "" : `<p class="gl-text${short ? " is-clamp" : ""}">${esc(text)}</p>${short ? `<details class="gl-full"><summary>게시물 전문</summary><p>${esc(text)}</p></details>` : ""}`}
        <p class="gl-claim">${status(it)}<span>${it.origin === "web" ? "모델" : "모델 주장"}: ${esc(claim)}</span></p>
        ${it.origin === "web" ? `<p class="gl-verif">출처에 적힌 확인 여부: ${esc(it.verification)}</p>` : ""}
        ${pc && pc.gate ? `<p class="gl-gate">${esc(pc.gate)}</p>` : ""}
        <p class="gl-why"><b>고른 이유</b> ${esc(it.reason)}</p>
        <p class="gl-meta">${who}${it.date ? ` · ${esc(it.date)}` : ""}${it.likes != null ? ` · 좋아요 ${it.likes.toLocaleString("en-US")} (수집 시점)` : ""}</p>
        <p class="gl-links"><a href="${raw(it.url)}" target="_blank" rel="noopener noreferrer" data-kind="${raw(it.linkKind)}">${esc(it.linkKind)}</a>${floorLink}</p>
        <p class="q-ref">${esc(it.src)}${it.textSrc && it.textSrc.l ? ` · 문구 ${esc(it.textSrc.f)} :${it.textSrc.l}` : ""}</p>
      </div></li>`;
  }
  const grid = (list, leadFirst) => `<ol class="gl-grid">${list.map((it, i) => tile(it, leadFirst && i === 0 && list.length > 2)).join("")}</ol>`;
  function showcase(s) {
    return G.families.map((f) => {
      const list = s.items.filter((i) => i.family === f.key);
      if (!list.length) return "";
      const groups = [...new Set(list.map((i) => i.group))];
      return `<div class="gl-famblock" data-fam="${f.key}"><h4 class="gl-fam-h"><b>${esc(f.name)}</b>${f.sub ? ` <span>${esc(f.sub)}</span>` : ""}<em>${list.length}</em></h4>
        ${groups.map((g) => { const l = list.filter((i) => i.group === g).sort(likes); return `<div class="gl-sub"><h5>${esc(g)}<span>${l.length}</span></h5>${grid(l, true)}</div>`; }).join("")}</div>`;
    }).join("");
  }
  function office(s) {
    const web = s.items.filter((i) => i.origin === "web").sort((a, b) => a.rank - b.rank);
    const x = s.items.filter((i) => i.origin !== "web" && !i.computerUse).sort(likes);
    const cu = s.items.filter((i) => i.computerUse);
    return `${web.length ? `<div class="gl-sub"><h5>웹 사례 (순위순)<span>${web.length}</span></h5><p class="gl-subnote">공식 출처 다섯 건은 확인됨, 제3자 튜토리얼 한 건은 미확인입니다. YouTube는 누를 때만 youtube-nocookie에서 불러옵니다.</p>${grid(web, false)}</div>` : ""}
      ${x.length ? `<div class="gl-sub"><h5>X 게시물<span>${x.length}</span></h5>${grid(x, false)}</div>` : ""}
      ${cu.length ? `<div class="gl-sub is-cu"><h5>컴퓨터 사용 데모<span>${cu.length}</span></h5><p class="gl-subnote">오피스로 분류된 12건 중 6건(#40~#45)은 실제 사무 업무가 아니라 컴퓨터 사용 시연이었습니다. 가장 볼 만한 한 건만 남겼습니다.</p>${grid(cu, false)}</div>` : ""}`;
  }
  function build() {
    const total = G.items.length;
    const bar = sections.map((s) => `<span class="gl-seg" data-sec="${s.key}" style="--w:${(s.items.length / total) * 100}%"><b>${s.items.length}</b><em>${esc(s.name)}</em></span>`).join("");
    const secHTML = sections.map((s) => `
      <section class="gl-fam" id="gl-${s.key}" data-sec="${s.key}"><h3><b>${esc(s.name)}</b><span class="gl-famsub">${esc(s.sub)}</span><span class="gl-n">${s.items.length}</span></h3>
        ${s.key === "showcase" ? showcase(s) : s.key === "office" ? office(s) : `<div class="gl-sub">${grid(s.items.slice().sort(likes), true)}</div>`}
      </section>`).join("");
    const n = (o) => G.items.filter((i) => i.origin === o).length;
    body.innerHTML = `
      <header class="gl-head">
        <button type="button" class="btn btn-quiet gl-x" data-close>바닥으로 <kbd>Esc</kbd></button>
        <h2 id="gallery-title">프런티어 모델 활용 사례</h2>
        <p class="gl-big"><b>${total}</b><span>눈에 띄는 것만 고른 사례. Drive usecases ${n("drive")}건, X 수집 ${n("scout")}건, 웹 오피스 ${n("web")}건</span></p>
        <p class="gl-note"><span class="st st-s" data-st="unverified">미확인</span> ${esc(G.note)} 웹 오피스 사례 중 공식 출처 다섯 건만 <span class="st st-s" data-st="verified">확인됨</span>입니다.</p>
        <div class="gl-bar" role="img" aria-label="${raw(sections.map((s) => `${s.name} ${s.items.length}건`).join(", "))}">${bar}</div>
        <nav class="gl-nav" aria-label="묶음으로 이동">${sections.map((s) => `<a href="#gl-${s.key}">${esc(s.name)} <span>${s.items.length}</span></a>`).join("")}</nav>
      </header>
      ${secHTML}
      <footer class="gl-foot"><p class="q-ref">출처: refs/drive/usecases/ (X 링크는 파일 이름에서), refs/old-claude-design-brief.md (Drive 게시물 첫 줄), refs/x-frontier-cases/cases.json, refs/web-office-cases/cases.json. 고른 기준과 이유: tools/curation.json. 미디어: tools/build_gallery.py.</p></footer>`;
    built = true;
  }
  let built = false, opener = null;

  function open(key) {
    if (!built) build();
    opener = document.activeElement;
    if (!dlg.open) dlg.showModal();
    window.ARchive && window.ARchive.pauseFloor && window.ARchive.pauseFloor();
    if (key && byKey.has(key)) {
      const el = document.getElementById("g-" + key);
      el && el.scrollIntoView({ block: "center" });
      el && el.querySelector("button, a")?.focus({ preventScroll: true });
    } else { dlg.scrollTop = 0; $(".gl-x", body).focus({ preventScroll: true }); }
    history.replaceState(null, "", "#gallery");
  }
  function close() {
    if (!dlg.open) return;
    dlg.querySelectorAll("video").forEach((v) => v.pause());
    dlg.querySelectorAll("iframe").forEach((f) => f.remove());
    dlg.close();
  }
  dlg.addEventListener("close", () => {
    history.replaceState(null, "", location.pathname + location.search);
    window.ARchive && window.ARchive.resumeFloor && window.ARchive.resumeFloor();
    if (opener && document.contains(opener)) opener.focus({ preventScroll: true });
    built = false; /* rebuilt on next open, so an embedded player never keeps running */
  });
  dlg.addEventListener("click", (e) => {
    const play = e.target.closest(".gl-play");
    if (play) {
      const v = document.createElement("video");
      v.src = play.dataset.src; v.controls = true; v.playsInline = true; v.preload = "none";
      v.poster = $("img", play).getAttribute("src"); v.setAttribute("aria-label", play.getAttribute("aria-label").replace(" 재생", ""));
      play.replaceWith(v); v.play().catch(() => {}); v.focus();
      return;
    }
    const yt = e.target.closest(".gl-yt");
    if (yt) {
      const f = document.createElement("iframe");
      f.src = `https://www.youtube-nocookie.com/embed/${encodeURIComponent(yt.dataset.yt)}?autoplay=1&rel=0`;
      f.title = yt.getAttribute("aria-label").replace(": YouTube 영상 불러오기", "");
      f.allow = "autoplay; encrypted-media; picture-in-picture; fullscreen"; f.loading = "lazy";
      f.referrerPolicy = "strict-origin-when-cross-origin";
      yt.replaceWith(f); f.focus();
      return;
    }
    const pc = e.target.closest(".gl-piece");
    if (pc) { close(); window.ARchive.openRoom(pc.dataset.piece); return; }
    const nav = e.target.closest(".gl-nav a");
    if (nav) { e.preventDefault(); document.querySelector(nav.getAttribute("href")).scrollIntoView({ behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" }); return; }
    if (e.target.closest("[data-close]") || e.target === dlg) close();
  });

  window.ARG = { open, close, get isOpen() { return dlg.open; } };
  buildWall();
  if (location.hash === "#gallery") requestAnimationFrame(() => open());
})();
